cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
#include <cuda_pipeline.h>
#define USE_CP_ASYNC 1
#else
#define USE_CP_ASYNC 0
#endif
using namespace cute;
// Cooperative tiled implicit-GEMM Conv2d forward kernel (CuTe).
// Optimization (one attempt): wider spatial output tiling.
// Each CTA covers a 32x64 output tile with 256 threads while
// using 2x4 register blocking. This raises per-thread arithmetic
// intensity and reduces CTA size to ease occupancy pressure from
// registers and shared memory while preserving the staged input tile,
// transposed W tile, vectorized shared-memory loads, 2-stage cp.async
// pipeline, and zero-fill of out-of-range lanes.
template <typename T>
__global__ void conv2d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C_in, int H, int Win,
    int C_out, int KH, int KW,
    int stride, int padding,
    int Hout, int Wout)
{
  constexpr int Threads = 256;
  constexpr int CTile   = 32;
  constexpr int PTile   = 64;
  constexpr int KTile   = 32;
  constexpr int TM      = 2;
  constexpr int TN      = 4;
  constexpr int SW_LD   = CTile + 2;  // padded LD of transposed W tile [K][C]
  constexpr int STAGES  = 2;
  const int tid = threadIdx.x;
  const int n      = blockIdx.z;
  const int c_base = blockIdx.y * CTile;
  const int p_block= blockIdx.x * PTile;
  const int P_total = Hout * Wout;
  const int K = C_in * KH * KW;
  const int64_t sXn = (int64_t)C_in * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)C_out * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const T* __restrict__ Xn = X + (int64_t)n * sXn;
  const int Kchunks = (K + KTile - 1) / KTile;
  extern __shared__ T s_raw[];
  // Double-buffered shared tiles.
  T* sX_raw0 = s_raw;
  T* sW_raw0 = s_raw + STAGES * KTile * PTile;
  const int thread_c = tid / (PTile / TN);
  const int thread_p = tid % (PTile / TN);
  const int c0 = c_base + thread_c * TM;
  const int p0 = p_block + thread_p * TN;
  float acc[TM][TN];
  #pragma unroll
  for (int i = 0; i < TM; ++i) {
    const int c = c0 + i;
    float bval = 0.0f;
    if (B != nullptr && c < C_out) {
      bval = (float)B[c];
    }
    #pragma unroll
    for (int j = 0; j < TN; ++j) {
      acc[i][j] = bval;
    }
  }
  // Asynchronous (or guarded scalar fallback) stage of one K-chunk into buffer `buf`.
  auto load_stage = [&](int k0, int buf) {
    T* sXr = sX_raw0 + buf * (KTile * PTile);
    T* sWr = sW_raw0 + buf * (KTile * SW_LD);
    // ---- stage W tile transposed as (KTile x CTile), padded leading dim ----
    #pragma unroll
    for (int it = 0; it < (CTile * KTile + Threads - 1) / Threads; ++it) {
      const int idx = tid + it * Threads;
      const int cc = idx / KTile;
      const int kk = idx - cc * KTile;
      const int c = c_base + cc;
      const int k = k0 + kk;
      T* dst = sWr + kk * SW_LD + cc;
      const bool valid = (c < C_out) && (k < K);
#if USE_CP_ASYNC
      if (valid) {
        const T* src = W + (int64_t)c * K + k;
        __pipeline_memcpy_async((void*)dst, (const void*)src, sizeof(T));
      } else {
        *dst = T(0);
      }
#else
      *dst = valid ? W[(int64_t)c * K + k] : T(0);
#endif
    }
    // ---- stage im2col X tile (KTile x PTile), row-major ----
    #pragma unroll
    for (int it = 0; it < (KTile * PTile + Threads - 1) / Threads; ++it) {
      const int idx = tid + it * Threads;
      const int kk = idx / PTile;
      const int pp = idx - kk * PTile;
      const int k = k0 + kk;
      const int p = p_block + pp;
      T* dst = sXr + kk * PTile + pp;
      bool valid = false;
      const T* src = Xn;
      if (k < K && p < P_total) {
        const int ic = k / (KH * KW);
        const int rem = k - ic * KH * KW;
        const int kh = rem / KW;
        const int kw = rem - kh * KW;
        const int oh = p / Wout;
        const int ow = p - oh * Wout;
        const int ih = oh * stride - padding + kh;
        const int iw = ow * stride - padding + kw;
        if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
          valid = true;
          src = Xn + (int64_t)ic * sXc + (int64_t)ih * sXh + iw;
        }
      }
#if USE_CP_ASYNC
      if (valid) {
        __pipeline_memcpy_async((void*)dst, (const void*)src, sizeof(T));
      } else {
        *dst = T(0);
      }
#else
      *dst = valid ? *src : T(0);
#endif
    }
#if USE_CP_ASYNC
    __pipeline_commit();
#endif
  };
  // Prologue: stage chunk 0.
  load_stage(0, 0);
  for (int kc = 0; kc < Kchunks; ++kc) {
    const int cur = kc & (STAGES - 1);
    const int nxt = cur ^ 1;
    // Prefetch next chunk into the other buffer before consuming current.
    if (kc + 1 < Kchunks) {
      load_stage((kc + 1) * KTile, nxt);
    }
#if USE_CP_ASYNC
    // Wait until the oldest outstanding group (current chunk) has landed.
    __pipeline_wait_prior((kc + 1 < Kchunks) ? 1 : 0);
#endif
    __syncthreads();
    const T* sXr = sX_raw0 + cur * (KTile * PTile);
    const T* sWr = sW_raw0 + cur * (KTile * SW_LD);
    #pragma unroll
    for (int kk = 0; kk < KTile; ++kk) {
      // Vectorized LDS: X tile is [K][P] and the W tile is staged transposed
      // as [K][C] with an even padded stride, so the TN input values and the
      // TM weight values are each contiguous and fetched with one 8-byte
      // shared-memory load instead of two 4-byte loads.
      const float4 xv4 = *reinterpret_cast<const float4*>(sXr + kk * PTile + thread_p * TN);
      const float xv[TN] = {xv4.x, xv4.y, xv4.z, xv4.w};
      const float2 wv2 = *reinterpret_cast<const float2*>(sWr + kk * SW_LD + thread_c * TM);
      const float wv[TM] = {wv2.x, wv2.y};
      #pragma unroll
      for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
          acc[i][j] += wv[i] * xv[j];
        }
      }
    }
    __syncthreads();
  }
  T* Yn = Y + (int64_t)n * sYn;
  #pragma unroll
  for (int i = 0; i < TM; ++i) {
    const int c = c0 + i;
    if (c >= C_out) continue;
    #pragma unroll
    for (int j = 0; j < TN; ++j) {
      const int p = p0 + j;
      if (p >= P_total) continue;
      const int oh = p / Wout;
      const int ow = p - oh * Wout;
      Yn[(int64_t)c * sYc + (int64_t)oh * sYh + ow] = static_cast<T>(acc[i][j]);
    }
  }
}
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C_in, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C_out, C_in, KH, KW]");
  int64_t N     = x.size(0);
  int64_t C_in  = x.size(1);
  int64_t H     = x.size(2);
  int64_t Win   = x.size(3);
  int64_t C_out = w.size(0);
  int64_t KH    = w.size(2);
  int64_t KW    = w.size(3);
  TORCH_CHECK(w.size(1) == C_in, "w.size(1) must equal C_in");
  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t K = C_in * KH * KW;
  TORCH_CHECK(K <= 1024, "C_in*KH*KW must be <= 1024 for this kernel");
  int64_t Hout = (H + 2 * padding - KH) / stride + 1;
  int64_t Wout = (Win + 2 * padding - KW) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C_out, "bias must be [C_out]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, C_out, Hout, Wout}, x.options());
  constexpr int Threads = 256;
  constexpr int CTile   = 32;
  constexpr int PTile   = 64;
  constexpr int KTile   = 32;
  constexpr int SW_LD   = CTile + 2;
  constexpr int STAGES  = 2;
  const int64_t P_total = Hout * Wout;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((C_out + CTile - 1) / CTile),
      (unsigned)N
  );
  const size_t smem_bytes =
      (size_t)STAGES * ((size_t)KTile * (size_t)PTile + (size_t)KTile * (size_t)SW_LD) * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_tiled_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C_in, (int)H, (int)Win,
      (int)C_out, (int)KH, (int)KW,
      (int)stride, (int)padding,
      (int)Hout, (int)Wout
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_11x11_s4_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Conv2d(3, 96, kernel_size=11, stride=4, padding=2) implemented with a
    single cooperative tiled CUDA kernel written with CuTe.
    """
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels,
                        self.kernel_size, self.kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size * self.kernel_size
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

